 * Thrown when creating an owner whose normalized telephone number is already used by another
 * owner. Carries the offending field name so the exception handler can report it in the
 * {@code errors} response body, and maps to a 409 Conflict response.
 */
public class DuplicateTelephoneException extends RuntimeException {

    private final List<String> fields;

    public DuplicateTelephoneException(String telephone) {
        super("An owner with telephone '" + telephone + "' already exists");
        this.fields = List.of("telephone");
    }

    public List<String> getFields() {
        return this.fields;
    }
}

